package com.abhishek.transcriptai.domain.model

/**
 * Domain model representing a downloaded transcript
 *
 * @param text Transcript text without timestamps
 * @param videoId YouTube video ID
 * @param videoTitle Video title, when YouTube returns one
 * @param languageCode Caption code of the track that was downloaded (e.g., "id", "pt-BR")
 * @param languageName Display name YouTube gives that track (e.g., "Indonesian")
 * @param isAutoGenerated Whether the track was generated by YouTube from the speech
 * @param requestedLanguageMatched False when none of the requested languages existed
 *        and another track was used instead
 * @param availableTracks Every caption track the video offers, for switching language
 */
data class SubtitleResult(
    val text: String,
    val videoId: String,
    val videoTitle: String? = null,
    val languageCode: String? = null,
    val languageName: String? = null,
    val isAutoGenerated: Boolean = false,
    val requestedLanguageMatched: Boolean = true,
    val availableTracks: List<CaptionTrack> = emptyList()
)

/**
 * One caption track a video offers
 *
 * @param languageCode YouTube caption code (e.g., "en", "es-419")
 * @param name Display name YouTube gives the track (e.g., "Spanish (Latin America)")
 * @param isAutoGenerated Whether YouTube generated it from the speech
 */
data class CaptionTrack(
    val languageCode: String,
    val name: String,
    val isAutoGenerated: Boolean
)

/**
 * Sealed class representing the result of an operation
 */
sealed class Result<out T> {
    data class Success<T>(val data: T) : Result<T>()
    data class Error(val message: String, val exception: Throwable? = null, val errorType: String? = null) : Result<Nothing>()
    data object Loading : Result<Nothing>()
}
